import { footprintReleaseBudgetPresentation, impactFootprintReleasePresentation, projectileFootprintReleasePresentation, specialistFootprintReleasePresentation, telegraphSafeLaneFootprintReleasePresentation } from './threat-impact-footprint-release-rendering.js';
const clamp01 = (value) => Math.max(0, Math.min(1, Number.isFinite(value) ? value : 0));
export function projectileCorridorReleasePresentation(input, reducedMotion = false) { const pressure = clamp01(input.pressure), release = clamp01(input.release), floor = input.critical ? .8 : .5, reclaim = clamp01(release * (1 - pressure * .25)), footprint = projectileFootprintReleasePresentation({ pressure, release, critical: input.critical }, reducedMotion); return { bodyAlphaScale: 1, trailAlphaScale: Math.min((floor + (1 - floor) * reclaim) * (reducedMotion ? .94 : 1), footprint.trailCeiling), reclaim, presentationOnly: true }; }
export function telegraphSafeLaneReleasePresentation(input, reducedFlash = false) { const overlap = clamp01(input.overlap), release = clamp01(input.release), hold = clamp01(overlap * (1 - release * .72)), flash = reducedFlash ? .9 : 1, footprint = telegraphSafeLaneFootprintReleasePresentation(input, reducedFlash); return { telegraphEdgeAlphaScale: input.telegraphActive ? Math.max(.92, .98 * (reducedFlash ? .98 : 1)) : 1, safeLaneAlphaScale: 1 + hold * .08 * (reducedFlash ? .76 : 1), secondaryAlphaScale: Math.min(Math.min(1, Math.max(.62, .68 + release * .32 - hold * .18)) * flash, footprint.secondaryCeiling), presentationOnly: true }; }
export function impactCorridorReleasePresentation(input, reducedFlash = false) { const life = clamp01(input.life), hero = clamp01(input.heroProximity), crowd = clamp01((Math.max(1, input.neighborCount) - 1) / 7), release = clamp01(input.release), pressure = clamp01(hero * .4 + crowd * .36 + (1 - life) * .22), reclaim = clamp01(release * (1 - pressure * .22)), flash = reducedFlash ? .9 : 1, footprint = impactFootprintReleasePresentation({ heroProximity: hero, crowd, release, critical: input.critical }, reducedFlash), fillAlphaScale = Math.min(Math.max(input.critical ? .56 : .24, .42 + .58 * reclaim) * flash, footprint.fillCeiling), edgeAlphaScale = Math.max(fillAlphaScale, .68 + .22 * reclaim); return { pressure, reclaim, canonicalAlphaScale: 1, fillAlphaScale, edgeAlphaScale, secondaryAlphaScale: Math.min(Math.max(.58, .66 + .34 * reclaim) * flash, footprint.secondaryCeiling), presentationOnly: true }; }
export function specialistDirectionalReleasePresentation(input, reducedMotion = false) { const hazard = clamp01(input.hazardPressure), recovery = clamp01(input.recovery), action = input.owner === 'special' ? 1 : input.owner === 'attack' ? .9 : input.owner === 'hit' ? .68 : input.owner === 'recovery' ? .5 : .15, reclaim = clamp01(recovery * (1 - hazard * .22)), footprint = specialistFootprintReleasePresentation({ owner: input.owner, hazardPressure: hazard, recovery }, reducedMotion); return { bodyAlphaScale: 1, directionAlphaScale: Math.max(.64, .72 + action * .2 + reclaim * .08 - hazard * .06), trailAlphaScale: Math.min(Math.max(.48, .56 + .44 * reclaim - hazard * .12) * (reducedMotion ? .9 : 1), footprint.trailCeiling), secondaryAlphaScale: Math.max(.6, .68 + .32 * reclaim - hazard * .08), presentationOnly: true }; }
export function spatialReclaimGuardPresentation(input, reducedFlash = false) { const release = clamp01(input.release), pressure = clamp01(input.pressure), reclaim = clamp01(release * (1 - pressure * .2)), flash = reducedFlash ? .92 : 1, footprint = footprintReleaseBudgetPresentation({ release, pressure, safeLaneVisible: input.safeLaneVisible, criticalCount: 0 }, false, reducedFlash); return { reclaim, canonicalBodyAlphaScale: 1, safeLaneAlphaScale: input.safeLaneVisible ? 1 + (1 - reclaim) * pressure * .06 * (reducedFlash ? .76 : 1) : 1, secondaryAlphaScale: Math.min(Math.max(.62, .62 + .38 * reclaim) * flash, footprint.secondaryCeiling), presentationOnly: true }; }
export function spatialRecoveryBudgetPresentation(input, reducedMotion = false, reducedFlash = false) { const count = clamp01(Math.max(0, input.recoveringCount - 1) / 11), pressure = clamp01(input.pressure), critical = clamp01(Math.max(0, input.criticalCount) / 3), stress = clamp01(count * .56 + pressure * .38 + critical * .1), footprint = footprintReleaseBudgetPresentation({ release: 1 - stress * .28, pressure, safeLaneVisible: false, criticalCount: input.criticalCount }, reducedMotion, reducedFlash); return { stress, criticalAlphaScale: 1, canonicalBodyAlphaScale: 1, secondaryRecoveryScale: Math.min(Math.max(.64, 1 - stress * .32) * (reducedMotion ? .94 : 1) * (reducedFlash ? .94 : 1), footprint.secondaryCeiling), presentationOnly: true }; }
